const int touchPin = {{touch_pin}};
const int threshold = {{threshold}};
bool wasTouched = false;

void setup() {
  Serial.begin(115200);
}

void loop() {
  int value = touchRead(touchPin);
  bool touched = value < threshold;
  if (touched && !wasTouched) {
    Serial.print("touch begin val=");
    Serial.println(value);
  } else if (!touched && wasTouched) {
    Serial.println("touch end");
  }
  wasTouched = touched;
  delay(30);
}
